class Solution { fun findMissingRanges(nums: IntArray, lower: Int, upper: Int): List<List<Int>> { val result = mutableListOf<List<Int>>(); var previous = lower.toLong() - 1; for (i in 0..nums.size) { val current = if (i == nums.size) upper.toLong() + 1 else nums[i].toLong(); if (current - previous >= 2) result.add(listOf((previous + 1).toInt(), (current - 1).toInt())); previous = current }; return result } }